import{_ as t,o as e,a,a3 as n}from"./chunks/framework.CnT1yzXN.js";const m=JSON.parse('{"title":"Mod Collections","description":"Mod collections in Stuzhik — version-independent sets of mods you can apply to any instance with one click.","frontmatter":{"description":"Mod collections in Stuzhik — version-independent sets of mods you can apply to any instance with one click.","head":[["meta",{"name":"keywords","content":"stuzhik mod collections, stuzhik, mod collections, minecraft mod sets, apply mods to instance"}]]},"headers":[],"relativePath":"en/guide/collections.md","filePath":"en/guide/collections.md"}'),i={name:"en/guide/collections.md"};function l(c,o,s,r,d,h){return e(),a("div",null,[...o[0]||(o[0]=[n('<h1 id="mod-collections" tabindex="-1">Mod Collections <a class="header-anchor" href="#mod-collections" aria-label="Permalink to &quot;Mod Collections&quot;">​</a></h1><p>A set of mods not tied to a specific Minecraft version or loader. You put it together once and apply it to any instance, and Stuzhik picks the right mod versions for it by itself.</p><p>This isn&#39;t a modpack: a collection contains no configs or settings — only the list of mods you usually install together.</p><h2 id="why-you-need-it" tabindex="-1">Why you need it <a class="header-anchor" href="#why-you-need-it" aria-label="Permalink to &quot;Why you need it&quot;">​</a></h2><p>A modpack pins versions. A collection doesn&#39;t. If you have a go-to set of your favorite mods (say, optimization + QoL) and you keep creating new instances for different MC versions — instead of reinstalling the same set by hand, you apply the collection, and the right versions are picked automatically for that particular instance.</p><h2 id="creating-a-collection" tabindex="-1">Creating a collection <a class="header-anchor" href="#creating-a-collection" aria-label="Permalink to &quot;Creating a collection&quot;">​</a></h2><h3 id="from-scratch" tabindex="-1">From scratch <a class="header-anchor" href="#from-scratch" aria-label="Permalink to &quot;From scratch&quot;">​</a></h3><ol><li>The &quot;Mod Collections&quot; section in the sidebar → type a name into the &quot;Collection name…&quot; field and click &quot;+&quot; (&quot;Create collection&quot;). With the field empty, &quot;+&quot; asks you for a name</li><li>A description (optional) — the &quot;Edit collection&quot; pencil next to the name</li><li>Add mods through the built-in catalog — the &quot;Catalog&quot; switch above the collection&#39;s mod list, with an &quot;Add&quot; button on each mod. Search, filters, everything just like in the regular mod browser</li></ol><h3 id="from-an-installed-instance" tabindex="-1">From an installed instance <a class="header-anchor" href="#from-an-installed-instance" aria-label="Permalink to &quot;From an installed instance&quot;">​</a></h3><ol><li>The &quot;Mod Collections&quot; section → the &quot;From instance&quot; button → pick the instance</li><li>Choose which mods to include (you don&#39;t have to take all of them). Only Modrinth and CurseForge mods are listed — local JARs can&#39;t be matched to another game version</li><li>Where to: &quot;To a new collection&quot; (give it a name) or &quot;To “…”&quot; — the collection that&#39;s open right now. Then &quot;Add&quot;</li></ol><h2 id="applying-a-collection" tabindex="-1">Applying a collection <a class="header-anchor" href="#applying-a-collection" aria-label="Permalink to &quot;Applying a collection&quot;">​</a></h2><h3 id="to-an-existing-instance" tabindex="-1">To an existing instance <a class="header-anchor" href="#to-an-existing-instance" aria-label="Permalink to &quot;To an existing instance&quot;">​</a></h3><ol><li>Instance → &quot;Mods&quot; tab → the &quot;Mod Collections&quot; button (tooltip &quot;Apply&quot;)</li><li>Choose a collection</li><li>Stuzhik shows a preview: what will be installed, what will be skipped (already there or incompatible), and what couldn&#39;t be found for this version/loader</li><li>Confirm with &quot;Install selected&quot;</li></ol><h3 id="when-creating-a-new-instance" tabindex="-1">When creating a new instance <a class="header-anchor" href="#when-creating-a-new-instance" aria-label="Permalink to &quot;When creating a new instance&quot;">​</a></h3><p>The instance creation form has an optional &quot;Mod collection&quot; field (it shows up once you have collections, and not for a vanilla instance) — the mods are installed right after the instance is created, with versions picked for its MC version and loader.</p><h2 id="export-and-import" tabindex="-1">Export and import <a class="header-anchor" href="#export-and-import" aria-label="Permalink to &quot;Export and import&quot;">​</a></h2><ul><li><strong>To a modpack</strong> — a collection can be exported to <code>.mrpack</code> (Modrinth) or <code>.stzhk</code> (Stuzhik format), pinning the versions for a specific MC version</li><li><strong>Importing a modpack into a collection</strong> — it works the other way around too: take an existing modpack (Modrinth or CurseForge) and save its mod list as a version-independent collection</li></ul><h2 id="management" tabindex="-1">Management <a class="header-anchor" href="#management" aria-label="Permalink to &quot;Management&quot;">​</a></h2><ul><li>Duplicate a collection — if you want to make a variation without touching the original</li><li>Renaming, a custom icon</li><li>Sorting the mods within a collection: &quot;By date added&quot;, &quot;By name&quot; or &quot;By source&quot;</li></ul><h2 id="what-s-next" tabindex="-1">What&#39;s next? <a class="header-anchor" href="#what-s-next" aria-label="Permalink to &quot;What&#39;s next?&quot;">​</a></h2><ul><li><a href="/en/guide/mods.html">Managing mods</a></li><li><a href="/en/guide/modpacks.html">Modpacks</a></li><li><a href="/en/faq.html">FAQ</a></li></ul>',21)])])}const p=t(i,[["render",l]]);export{m as __pageData,p as default};
